import importlib.util, json, numpy as np, copy
def loadmod(name,path):
    spec=importlib.util.spec_from_file_location(name,path)
    m=importlib.util.module_from_spec(spec); spec.loader.exec_module(m); return m
lp=loadmod('lp','/root/lp_market.py')
cv=loadmod('cv','/root/solve_market.py')
d=json.load(open('/root/network.json'))
# rename keys between modules
def solve_lp_relax(flag):
    return lp.solve_lp(d,flag)
def solve_cv_relax(flag):
    return cv.solve_case(d,relax_target=flag)
for flag in (False,True):
    a=solve_lp_relax(flag); b=solve_cv_relax(flag)
    am={x['bus']:x['lmp_dollars_per_MWh'] for x in a['lmp_by_bus']}
    bm={x['bus']:x['lmp_dollars_per_MWh'] for x in b['lmp_by_bus']}
    diffs=sorted(((abs(am[k]-bm[k]),k,am[k],bm[k]) for k in am),reverse=True)
    print('flag',flag,'maxdiff',diffs[0],'count>0.05',sum(1 for x in diffs if x[0]>0.05))
    print('  top3 diffs',diffs[:3])
# FD check of LP marginals
base=lp.solve_lp(d,False)
lm={x['bus']:x['lmp_dollars_per_MWh'] for x in base['lmp_by_bus']}
for busnum in (9,64,1501,629,676,1266,1709,1728):
    d2=copy.deepcopy(d)
    for b in d2['bus']:
        if int(b[0])==busnum: b[2]+=1.0
    r=lp.solve_lp(d2,False)
    print('FD',busnum,'lmp_report',lm[busnum],'fd',round(r['total_cost_dollars_per_hour']-base['total_cost_dollars_per_hour'],4))
