import numpy as np
from r2r_simulator import R2RSimulator
from scipy.linalg import solve_discrete_are
sim=R2RSimulator(); p=sim.get_params()
EA,J,R,fb,L,v0,dt,n=p['EA'],p['J'],p['R'],p['fb'],p['L'],p['v0'],p['dt'],p['num_sections']
T0=np.array([28,36,20,40,24,32],float); vr=sim._compute_velocities(T0)
Ac=np.zeros((12,12));Bc=np.zeros((12,6))
for i in range(n):
    if i==0:
        Ac[i,i]+=-vr[i]/L; Ac[i,n+i]+=EA/L-T0[i]/L
    else:
        Ac[i,i-1]+=vr[i-1]/L; Ac[i,i]+=-vr[i]/L; Ac[i,n+i-1]+=-EA/L+T0[i-1]/L; Ac[i,n+i]+=EA/L-T0[i]/L
    Ac[n+i,i]+=-R**2/J
    if i<n-1: Ac[n+i,i+1]+=R**2/J
    Ac[n+i,n+i]+=-fb/J; Bc[n+i,i]=R/J
Ad=np.eye(12)+dt*Ac; Bd=dt*Bc; I=np.eye(12); Rn=I*sim.noise_std**2
def lqr(Qd,Rd):
    Q=np.diag(Qd); Rm=np.diag(Rd); P=solve_discrete_are(Ad,Bd,Q,Rm)
    return np.linalg.solve(Rm+Bd.T@P@Bd,Bd.T@P@Ad)
def run(Qd,Rd,qn=1e-7,gamma=0.95,cI=0.15,intg=True,clipu=6,seed=0,steps=620):
    K=lqr(Qd,Rd); sim.reset(); np.random.seed(seed); uI=np.zeros(6); xhat=sim._get_measurement().copy(); Pf=I*1e-5; log=[];u=np.zeros(6); y=xhat.copy()
    for k in range(steps):
        if k>0:
            Pf=Ad@Pf@Ad.T+I*qn; Kf=Pf@np.linalg.inv(Pf+Rn); xhat=xhat+Kf@(y-xhat); Pf=(I-Kf)@Pf
        xr,ur=sim.get_reference(); u=ur-K@(xhat-xr)+(uI if intg else 0); u=np.clip(u,-clipu,clipu)
        y=sim.step(u); xhat=Ad@xhat+Bd@u
        if intg: uI=np.clip(gamma*uI-cI*dt*(xhat[:6]-xr[:6]),-1.5,1.5)
        log.append((sim.get_time(),y.copy(),u.copy(),xr.copy(),sim.T.copy(),ur.copy()))
    t=np.array([a[0] for a in log]);T=np.array([a[4][:6] for a in log]);U=np.array([a[2] for a in log]);Xr=np.array([a[3][:6] for a in log]);Ur=np.array([a[5] for a in log]);e=np.abs(T-Xr)
    res={}
    for tol in [0.5,1.0,2.0]:
        viol=np.any(e>tol,axis=1); m=t>=0.5; idx=np.where(m&viol)[0]; st=t[idx[-1]]-0.5 if len(idx) else 0; res[tol]=st
    du=np.abs(U-Ur); post=du[t>1.5].mean()
    return res,e[t>5].mean(),e.mean(),T.max(),T.min(),np.abs(U).max(),T[-1,2],post
for qv in [0.1,1e-3,1e-5]:
  for Rd in [0.033,0.5,2.0]:
    for qn in [1e-8,1e-7,1e-6,1e-5]:
      r=run([100]*6+[qv]*6,[Rd]*6,qn=qn)
      print(f"qv={qv} Rd={Rd} qn={qn}: s05 {r[0][.5]:.2f} s1 {r[0][1]:.2f} s2 {r[0][2]:.2f} last {r[1]:.3f} mean {r[2]:.3f} maxT {r[3]:.2f} minT {r[4]:.2f} maxu {r[5]:.2f} T3 {r[6]:.2f} du {r[7]:.2f}")
