import random, math, time, sys, json
from common import *

def valid_late(seq):
    return not any(seq[p] in LARGE for p in range(N-3,N))

def rand_valid(rng):
    seq=BLOCKS[:]
    rng.shuffle(seq)
    for pos in range(N-3,N):
        if seq[pos] in LARGE:
            cand=[k for k in range(0,N-3) if seq[k] not in LARGE]
            k=rng.choice(cand)
            seq[pos],seq[k]=seq[k],seq[pos]
    return seq

def local_descent(seq, rng, max_rounds=100):
    cur=objective(seq)
    improved=True; rounds=0
    while improved and rounds<max_rounds:
        improved=False; rounds+=1
        # randomized order of swaps then insertions
        # best-improvement swap neighborhood
        bestd=0; bestmv=None
        for i in range(N):
            for j in range(i+1,N):
                seq[i],seq[j]=seq[j],seq[i]
                if valid_late(seq):
                    d=objective(seq)-cur
                    if d<bestd-1e-9:
                        bestd=d; bestmv=('s',i,j)
                seq[i],seq[j]=seq[j],seq[i]
        # insertion neighborhood
        for i in range(N):
            for j in range(N):
                if i==j: continue
                v=seq.pop(i); seq.insert(j,v)
                if valid_late(seq):
                    d=objective(seq)-cur
                    if d<bestd-1e-9:
                        bestd=d; bestmv=('i',i,j)
                seq.pop(j); seq.insert(i,v)
        # segment reversal neighborhood (only boundary changes)
        for i in range(N-1):
            for j in range(i+1,N):
                seq[i:j+1]=reversed(seq[i:j+1])
                if valid_late(seq):
                    d=objective(seq)-cur
                    if d<bestd-1e-9:
                        bestd=d; bestmv=('r',i,j)
                seq[i:j+1]=reversed(seq[i:j+1])
        if bestmv is not None:
            t,i,j=bestmv
            if t=='s': seq[i],seq[j]=seq[j],seq[i]
            elif t=='i':
                v=seq.pop(i); seq.insert(j,v)
            else:
                seq[i:j+1]=reversed(seq[i:j+1])
            cur+=bestd
            improved=True
    return cur

def double_bridge(seq,rng):
    # cut into 4 nonempty-ish parts
    cuts=sorted(rng.sample(range(1,N),3))
    a,b,c=cuts
    A=seq[:a]; B=seq[a:b]; C=seq[b:c]; D=seq[c:]
    new=A+D+C+B
    # repair late validity by swapping large in late with nonlarge early if needed
    if not valid_late(new):
        for pos in range(N-3,N):
            if new[pos] in LARGE:
                cand=[k for k in range(0,N-3) if new[k] not in LARGE]
                if not cand: return seq[:]  # shouldn't happen
                k=rng.choice(cand)
                new[pos],new[k]=new[k],new[pos]
    return new

def ils(seed=0, kicks=5000, verbose=True):
    rng=random.Random(seed)
    seq=rand_valid(rng)
    cur=local_descent(seq,rng)
    best=cur; best_seq=seq[:]
    t0=time.time()
    for k in range(kicks):
        cand=double_bridge(best_seq if rng.random()<0.5 else seq,rng)
        # small random swaps sometimes
        if rng.random()<0.3:
            i,j=rng.sample(range(N),2); cand[i],cand[j]=cand[j],cand[i]
        if not valid_late(cand): continue
        v=local_descent(cand,rng)
        if v<best:
            best=v; best_seq=cand[:]
            if verbose: print(f"kick {k} best {best} t={time.time()-t0:.1f}s",flush=True)
        # ILS acceptance: restart from best if candidate much worse
        if v<=cur or rng.random()<0.02:
            seq=cand; cur=v
        else:
            seq=best_seq[:]; cur=best
    return best,best_seq

if __name__=='__main__':
    seed=int(sys.argv[1]) if len(sys.argv)>1 else 0
    kicks=int(sys.argv[2]) if len(sys.argv)>2 else 5000
    b,bseq=ils(seed,kicks)
    print("BEST",b)
    print(bseq)
    print(components(bseq),valid(bseq))
    with open(f'/root/work/best_ils_{seed}.json','w') as f:
        json.dump({'seq':bseq,'obj':b,'components':components(bseq)},f,indent=2)
