#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include "data.h"

static uint64_t rng_state;
static inline uint64_t xrand(){ uint64_t x=rng_state; x^=x<<13; x^=x>>7; x^=x<<17; rng_state=x; return x; }
static inline int rnd(int n){ return (int)(xrand()% (uint64_t)n); }

static inline int valid_late(const int *s){
    return !(LARGE[s[N-3]]||LARGE[s[N-2]]||LARGE[s[N-1]]);
}

static inline long long objective(const int *s){
    long long o=0;
    for(int t=0;t<N-1;t++) o += P[s[t]][s[t+1]];
    for(int t=0;t<N-2;t++){
        int w = (t<=N-4)?15:10;
        o += (long long)w*T[s[t]][s[t+1]][s[t+2]];
    }
    for(int t=0;t<N-3;t++) o += 5LL*T[s[t]][s[t+2]][s[t+3]];
    return o;
}

static void repair(int *s){
    for(int pos=N-3;pos<N;pos++){
        if(LARGE[s[pos]]){
            int cand[64],nc=0;
            for(int k=0;k<N-3;k++) if(!LARGE[s[k]]) cand[nc++]=k;
            if(nc==0) return;
            int k=cand[rnd(nc)];
            int tmp=s[pos]; s[pos]=s[k]; s[k]=tmp;
        }
    }
}

// best-improvement local search over swap / insertion / reversal
static long long local_search(int *s){
    long long cur=objective(s);
    int tmp[N];
    for(;;){
        long long bestd=0; int bt=-1,bi=-1,bj=-1;
        // swaps
        for(int i=0;i<N;i++) for(int j=i+1;j<N;j++){
            int a=s[i],b=s[j]; s[i]=b; s[j]=a;
            if(valid_late(s)){
                long long d=objective(s)-cur;
                if(d<bestd){ bestd=d; bt=0; bi=i; bj=j; }
            }
            s[i]=a; s[j]=b;
        }
        // insertions
        for(int i=0;i<N;i++) for(int j=0;j<N;j++){
            if(i==j) continue;
            memcpy(tmp,s,sizeof(int)*N);
            int v=tmp[i];
            if(i<j){ for(int k=i;k<j;k++) tmp[k]=tmp[k+1]; }
            else { for(int k=i;k>j;k--) tmp[k]=tmp[k-1]; }
            tmp[j]=v;
            if(valid_late(tmp)){
                long long d=objective(tmp)-cur;
                if(d<bestd){ bestd=d; bt=1; bi=i; bj=j; }
            }
        }
        // reversals
        for(int i=0;i<N-1;i++) for(int j=i+1;j<N;j++){
            memcpy(tmp,s,sizeof(int)*N);
            for(int k=i;k<=j;k++) tmp[k]=s[j-(k-i)];
            if(valid_late(tmp)){
                long long d=objective(tmp)-cur;
                if(d<bestd){ bestd=d; bt=2; bi=i; bj=j; }
            }
        }
        if(bt<0) break;
        if(bt==0){ int a=s[bi]; s[bi]=s[bj]; s[bj]=a; }
        else if(bt==1){ int v=s[bi]; if(bi<bj){ for(int k=bi;k<bj;k++) s[k]=s[k+1]; } else { for(int k=bi;k>bj;k--) s[k]=s[k-1]; } s[bj]=v; }
        else { for(int k=bi;k<=bj;k++) tmp[k]=s[bj-(k-bi)]; memcpy(s,tmp,sizeof(int)*N); }
        cur += bestd;
    }
    return cur;
}

static void perturb(int *s){
    int tmp[N];
    int a=1+rnd(N-3);
    int b=a+1+rnd(N-1-a);
    int c=b+1+rnd(N-b-1);
    int idx=0;
    for(int k=0;k<a;k++) tmp[idx++]=s[k];
    for(int k=c;k<N;k++) tmp[idx++]=s[k];
    for(int k=b;k<c;k++) tmp[idx++]=s[k];
    for(int k=a;k<b;k++) tmp[idx++]=s[k];
    memcpy(s,tmp,sizeof(int)*N);
    // extra kicks
    int r=rnd(100);
    if(r<25){ int i=rnd(N),j=rnd(N); int t=s[i]; s[i]=s[j]; s[j]=t; }
    else if(r<45){ // reverse random segment
        int i=rnd(N-1), j=i+1+rnd(N-1-i);
        for(int k=i;k<=j;k++) tmp[k]=s[j-(k-i)];
        for(int k=i;k<=j;k++) s[k]=tmp[k];
    } else if(r<60){ // move segment
        int i=rnd(N), j=rnd(N); if(i!=j){ int v=s[i]; if(i<j){for(int k=i;k<j;k++)s[k]=s[k+1];}else{for(int k=i;k>j;k--)s[k]=s[k-1];} s[j]=v; }
    }
    repair(s);
}

// SA polish
static void sa_polish(int *s, long long *curp, int iters, double T0, double T1){
    long long cur=*curp;
    double T=T0, ratio=pow(T1/T0,1.0/(iters>1?iters-1:1));
    int tmp[N];
    for(int it=0; it<iters; it++){
        memcpy(tmp,s,sizeof(int)*N);
        int r=rnd(100);
        int i=rnd(N), j=rnd(N);
        if(r<60){ int t=tmp[i]; tmp[i]=tmp[j]; tmp[j]=t; }
        else if(r<90){ if(i!=j){ int v=tmp[i]; if(i<j){for(int k=i;k<j;k++)tmp[k]=tmp[k+1];}else{for(int k=i;k>j;k--)tmp[k]=tmp[k-1];} tmp[j]=v; } }
        else { if(i<j){ for(int k=i;k<=j;k++){ int t2=tmp[k]; tmp[k]=tmp[j-(k-i)]; } } }
        if(!valid_late(tmp)){ T*=ratio; continue; }
        long long no=objective(tmp);
        long long d=no-cur;
        if(d<=0 || ((double)(xrand()%1000000)/1000000.0) < exp(-(double)d/T)){
            memcpy(s,tmp,sizeof(int)*N); cur=no;
        }
        T*=ratio;
    }
    *curp=cur;
}

int main(int argc,char**argv){
    int seed = argc>1?atoi(argv[1]):1;
    long long kicks = argc>2?atoll(argv[2]):200000;
    rng_state = (uint64_t)seed*88172645463325252ULL + 123456789ULL;
    if(rng_state==0) rng_state=1;
    for(int i=0;i<50;i++) xrand();

    int s[N]; for(int i=0;i<N;i++) s[i]=i;
    // shuffle
    for(int i=N-1;i>0;i--){ int j=rnd(i+1); int t=s[i]; s[i]=s[j]; s[j]=t; }
    repair(s);
    long long cur=local_search(s);
    int bests[N]; memcpy(bests,s,sizeof(int)*N);
    long long best=cur;
    int curses[N]; memcpy(curses,s,sizeof(int)*N);
    int curseq[N]; memcpy(curseq,s,sizeof(int)*N);

    time_t start=time(NULL);
    for(long long k=0;k<kicks;k++){
        int cand[N];
        if((xrand()&1)) memcpy(cand,bests,sizeof(int)*N);
        else memcpy(cand,curseq,sizeof(int)*N);
        perturb(cand);
        long long v=local_search(cand);
        if(v<best){
            best=v; memcpy(bests,cand,sizeof(int)*N);
            // occasional polish
            long long pc=best; sa_polish(bests,&pc,5000,50.0,0.1);
            pc=local_search(bests); best=pc;
            fprintf(stderr,"seed %d kick %lld best %lld t=%lds\n",seed,k,best,(long)(time(NULL)-start));
        }
        if(v<=cur || (xrand()%1000)<10){
            cur=v; memcpy(curseq,cand,sizeof(int)*N);
            memcpy(curses,cand,sizeof(int)*N);
        } else {
            cur=best; memcpy(curseq,bests,sizeof(int)*N);
        }
    }
    // final polish on best
    long long pc=best; sa_polish(bests,&pc,200000,100.0,0.05); pc=local_search(bests); best=pc;
    printf("%lld\n",best);
    for(int i=0;i<N;i++) printf("%d%c",bests[i]+1,i==N-1?'\n':' ');
    char fn[256]; snprintf(fn,sizeof(fn),"/root/work/cbest_%d.txt",seed);
    FILE*f=fopen(fn,"w"); fprintf(f,"%lld\n",best); for(int i=0;i<N;i++) fprintf(f,"%d%c",bests[i]+1,i==N-1?'\n':' '); fclose(f);
    return 0;
}
